126	// Feeds a regular file's complete raw bytes to sink:
127	//   start()             once, immediately after the file is opened;
128	//   consume(data, size) for every non-empty chunk, including a final short
129	//                       one (a zero-length file yields no consume() call);
130	//   finish()            exactly once, only after a read reaching normal EOF.
131	// A false return aborts the operation and the sink is responsible for its own
132	// diagnostic. read() on a regular file is allowed to return fewer bytes than
133	// requested without meaning EOF (an interrupt, a short kernel read, ...), so
134	// each pass keeps reading until the buffer fills or read() reports zero; only
135	// a zero return is normal EOF. A read error -- including one after some bytes
136	// were already delivered -- is reported as such and never reaches finish(), so
137	// a mid-read failure can never surface as a digest, a match/mismatch result
138	// or a key fingerprint.
139	template <typename ByteSink>
140	bool processFileChunks(const char* pathArg, ByteSink& sink) {
141	    const int openedFd = openRegularInput(pathArg);
142	    if (openedFd < 0) {
143	        return false;
144	    }
145	    FdGuard fdGuard(openedFd);
146	    if (!sink.start()) {
147	        return false;
148	    }
149	
150	    std::vector<char> buffer(kReadChunkSize);
151	    while (true) {
152	        size_t filled = 0;
153	        bool reachedEof = false;
154	        while (filled < buffer.size()) {
155	            ssize_t got = 0;
156	            do {
157	                got = ::read(openedFd, buffer.data() + filled,
158	                             buffer.size() - filled);
159	            } while (got < 0 && errno == EINTR);
160	            if (got < 0) {
161	                // The file was already opened successfully; this is a
162	                // read-stage failure, never an open error or a content/format
163	                // problem -- even if earlier bytes of this pass were already
164	                // delivered to the sink.
165	                std::cerr << "sealmark: failed to read '" << pathArg
166	                          << "'\n";
167	                return false;
168	            }
169	            if (got == 0) {
170	                reachedEof = true;  // normal end of file
171	                break;
172	            }
173	            const size_t n = static_cast<size_t>(got);
174	            if (!sink.consume(buffer.data() + filled, n)) {
175	                return false;
176	            }
177	            filled += n;
178	        }
179	        if (reachedEof) {
180	            break;
181	        }
182	    }
183	
184	    return sink.finish();
185	}
