585	// Renders bytes as lowercase hexadecimal with no separators or prefix.
586	std::string toHexLower(const unsigned char* data, size_t size) {
587	    static constexpr char kHex[] = "0123456789abcdef";
588	    std::string out;
589	    out.reserve(2 * size);
590	    for (size_t i = 0; i < size; ++i) {
591	        out.push_back(kHex[data[i] >> 4]);
592	        out.push_back(kHex[data[i] & 0x0f]);
593	    }
594	    return out;
595	}
596	
597	int digestFile(const char* pathArg) {
598	    Sha256StreamSink sink(pathArg);
599	    if (!processFileChunks(pathArg, sink)) {
600	        return 1;
601	    }
602	
603	    std::cout << kDigestPrefix
604	              << toHexLower(sink.hash(), kSha256Size) << '\n';
605	    return 0;
606	}
607	
608	// Accepts only "sha256:" followed by exactly 64 lowercase hexadecimal
609	// characters: no missing prefix, no uppercase, no other algorithm names,
610	// no surrounding whitespace or trailing content.
611	bool isValidExpectedDigest(std::string_view digest) {
612	    if (digest.size() != kDigestPrefix.size() + kDigestHexLen) {
613	        return false;
614	    }
615	    if (digest.substr(0, kDigestPrefix.size()) != kDigestPrefix) {
616	        return false;
617	    }
618	    for (size_t i = kDigestPrefix.size(); i < digest.size(); ++i) {
619	        const char c = digest[i];
620	        const bool isHex =
